use crate::term::TermRef;
use crate::value::{ValueRef, Env, Closure};

pub fn eval(env: &Env, term: &TermRef) -> ValueRef {
    match term.as_ref() {
        Term::Var(i) => {
            let idx = env.len() - 1 - *i;
            env[idx].clone()
        }
        Term::Lam(body) => {
            VLam(Closure(env, body))
        }
        Term::App(func, arg) => {
            env.push(arg);
            eval(&env, &func)
        }
    }
}

