#[test]
fn const_returns_first_argument() {
    // (λx. λy. x)(λz. z)(λw. w)  — should return the FIRST argument: the identity
    let konst = lam(lam(var(1)));
    let id = lam(var(0));
    let v = eval(&Vec::new(), &app(app(konst, id.clone()), id));
    match v.as_ref() {
        Value::VLam(c) => {
            assert_eq!(c.body, var(0));
            assert!(c.env.is_empty());
        }
        _ => panic!("expected a lambda value"),
    }
}
```

